import {actionTypesToEvents, registerCardComponent} from "@pihanga2/core";

import {ToggleGroupComponent} from "./toggleGroup.component";
import {
  PI_TOGGLE_GROUP_ACTION,
  PI_TOGGLE_GROUP_CARD,
} from "./toggleGroup.types";

export * from "./toggleGroup.types";

registerCardComponent({
  name: PI_TOGGLE_GROUP_CARD,
  component: ToggleGroupComponent,
  events: actionTypesToEvents(PI_TOGGLE_GROUP_ACTION),
});

import React from "react";
import {type PiCardProps} from "@pihanga2/core";
import {
  ToggleGroup as ToggleGroupUI,
  ToggleGroupItem,
} from "@/components/ui/toggle-group";
import {useFormContext} from "@/cards/form/form.context";
import type {
  PiToggleGroupEvents,
  PiToggleGroupProps,
} from "./toggleGroup.types";

export const ToggleGroupComponent = (
  props: PiCardProps<PiToggleGroupProps, PiToggleGroupEvents>,
): React.ReactNode => {
  const {
    name,
    items,
    type = "single",
    value: propValue,
    selfManaged = false,
    variant = "default",
    size = "default",
    spacing = 0,
    disabled,
    className,
    cardName,
    onChanged,
  } = props;

  // Detect if we are inside a pi/form card via React context.
  const form = useFormContext();
  const useFormData = form.isInForm && Boolean(name);

  // ---------------------------------------------------------------------------
  // Self-managed (internal) state — only active when selfManaged=true and we
  // are NOT inside a pi/form card.
  // ---------------------------------------------------------------------------
  const initialSelfValue: string | string[] =
    type === "multiple"
      ? Array.isArray(propValue)
        ? propValue
        : propValue != null
          ? [String(propValue)]
          : []
      : typeof propValue === "string"
        ? propValue
        : "";

  const [internalValue, setInternalValue] = React.useState<string | string[]>(
    initialSelfValue,
  );

  // ---------------------------------------------------------------------------
  // Derive the effective value from the appropriate source.
  //   1. Form context (highest priority)
  //   2. Self-managed internal state
  //   3. Externally controlled prop value
  // ---------------------------------------------------------------------------
  const formRawValue = useFormData ? form.formData[name!] : undefined;
  const value: string | string[] = useFormData
    ? type === "multiple"
      ? Array.isArray(formRawValue)
        ? (formRawValue as string[])
        : formRawValue != null
          ? [String(formRawValue)]
          : []
      : formRawValue != null
        ? String(formRawValue)
        : ""
    : selfManaged
      ? internalValue
      : (propValue ?? (type === "multiple" ? [] : ""));

  function handleSingleChange(newValue: string) {
    if (useFormData) {
      form.handleChange(name!, newValue);
    } else {
      if (selfManaged) {
        setInternalValue(newValue);
      }
      onChanged({name: name ?? cardName, value: newValue});
    }
  }

  function handleMultipleChange(newValue: string[]) {
    if (useFormData) {
      form.handleChange(name!, newValue);
    } else {
      if (selfManaged) {
        setInternalValue(newValue);
      }
      onChanged({name: name ?? cardName, value: newValue});
    }
  }

  // Render single-selection group
  if (type === "single") {
    return (
      <ToggleGroupUI
        data-pihanga={cardName}
        type="single"
        value={typeof value === "string" ? value : ""}
        onValueChange={handleSingleChange}
        variant={variant}
        size={size}
        spacing={spacing}
        disabled={disabled}
        className={className}
      >
        {items.map((item) => (
          <ToggleGroupItem
            key={item.value}
            value={item.value}
            disabled={item.disabled}
          >
            {item.label}
          </ToggleGroupItem>
        ))}
      </ToggleGroupUI>
    );
  }

  // Render multiple-selection group
  return (
    <ToggleGroupUI
      data-pihanga={cardName}
      type="multiple"
      value={Array.isArray(value) ? value : value ? [value] : []}
      onValueChange={handleMultipleChange}
      variant={variant}
      size={size}
      spacing={spacing}
      disabled={disabled}
      className={className}
    >
      {items.map((item) => (
        <ToggleGroupItem
          key={item.value}
          value={item.value}
          disabled={item.disabled}
        >
          {item.label}
        </ToggleGroupItem>
      ))}
    </ToggleGroupUI>
  );
};

import {
  createCardDeclaration,
  createOnAction,
  registerActions,
} from "@pihanga2/core";

export const PI_TOGGLE_GROUP_CARD = "pi/toggle-group";

export const ToggleGroup = createCardDeclaration<
  PiToggleGroupProps,
  PiToggleGroupEvents
>(PI_TOGGLE_GROUP_CARD);

export const PI_TOGGLE_GROUP_ACTION = registerActions(PI_TOGGLE_GROUP_CARD, [
  "changed",
]);

export const onToggleGroupChanged = createOnAction<PiToggleGroupChangedEvent>(
  PI_TOGGLE_GROUP_ACTION.CHANGED,
);

/** @deprecated Use `onToggleGroupChanged` instead. */
export const onPiToggleGroupChanged = onToggleGroupChanged;

// ---------------------------------------------------------------------------
// Item type
// ---------------------------------------------------------------------------

export type PiToggleGroupItem = {
  /** The value associated with this toggle item. */
  value: string;
  /** Human-readable label rendered inside the toggle button. */
  label: string;
  /** When true, this individual item is disabled. */
  disabled?: boolean;
};

// ---------------------------------------------------------------------------
// Props & Events
// ---------------------------------------------------------------------------

export type PiToggleGroupProps = {
  /**
   * Field name used to bind to FormContext when inside a pi/form card.
   * When provided the component reads its selected value from form data and
   * writes back via form.handleChange.
   */
  name?: string;

  /**
   * The list of toggle items to display.
   */
  items: PiToggleGroupItem[];

  /**
   * Selection mode.
   * - `"single"` — at most one item can be active at a time.
   * - `"multiple"` — any number of items can be active simultaneously.
   *
   * @default "single"
   */
  type?: "single" | "multiple";

  /**
   * Controlled selected value(s).
   * - In `"single"` mode: a `string` (or `undefined` for nothing selected).
   * - In `"multiple"` mode: an array of `string`.
   *
   * Ignored when `name` is set and the component is inside a pi/form.
   * Also ignored when `selfManaged` is `true`.
   */
  value?: string | string[];

  /**
   * When `true`, the component manages its own selection state internally
   * using `React.useState`.  The `value` prop is used only as the initial
   * value (i.e. `defaultValue`) and subsequent changes do not require an
   * external state update.  `onChanged` is still fired so callers can
   * observe changes without owning the state.
   *
   * Has no effect when inside a pi/form (form context always takes
   * precedence).
   *
   * @default false
   */
  selfManaged?: boolean;

  /**
   * Visual style variant of the toggle buttons.
   * - `"default"` — transparent background, highlights on active.
   * - `"outline"` — bordered buttons, grouped or spaced.
   *
   * @default "default"
   */
  variant?: "default" | "outline";

  /**
   * Size of each toggle button.
   * @default "default"
   */
  size?: "default" | "sm" | "lg";

  /**
   * Gap between toggle buttons (in Tailwind spacing units).
   * `0` = buttons are joined (no gap, rounded ends only).
   * Positive values add space between each button.
   *
   * @default 0
   */
  spacing?: number;

  /** When true, the entire group is disabled and non-interactive. */
  disabled?: boolean;

  /** Extra Tailwind / CSS classes forwarded to the root element. */
  className?: string;
};

export type PiToggleGroupChangedEvent = {
  /** Field name, mirrors the `name` prop if provided. */
  name?: string;
  /**
   * New selected value(s).
   * - In `"single"` mode: a `string` (empty string when nothing selected).
   * - In `"multiple"` mode: an array of `string`.
   */
  value: string | string[];
};

export type PiToggleGroupEvents = {
  onChanged: PiToggleGroupChangedEvent;
};
